const form = document.getElementById("inference-form");
const endpoint = document.getElementById("endpoint");
const randomButton = document.getElementById("random-button");
const retryButton = document.getElementById("retry-button");
const status = document.getElementById("status");
const canvas = document.getElementById("image");
const context = canvas.getContext("2d");
const results = document.getElementById("results");
const predictionCard = document.getElementById("prediction-card");
const prediction = document.getElementById("prediction");
const comparison = document.getElementById("comparison");
const elapsed = document.getElementById("elapsed");
const rows = [];
let testPixels;
let currentIndex = -1;
let busy = false;

function setStatus(message, isError = false) {
  status.textContent = message;
  status.classList.toggle("error", isError);
}

function setBusy(value) {
  busy = value;
  randomButton.disabled = value;
  retryButton.disabled = value;
  endpoint.disabled = value;
  randomButton.textContent = value ? "Waiting for ESP32…" : "Random image & infer";
  results.setAttribute("aria-busy", String(value));
}

function clearResults() {
  predictionCard.className = "prediction";
  prediction.textContent = "Awaiting inference";
  comparison.textContent = "Choose an image and send it to your board.";
  elapsed.textContent = "";
  for (const { row, value, tag } of rows) {
    row.classList.remove("winner");
    value.textContent = "—";
    tag.hidden = true;
  }
}

function selectRandomImage() {
  // Exclude the current image when choosing the next one.
  currentIndex = currentIndex < 0
    ? Math.floor(Math.random() * TEST_SAMPLES.length)
    : (currentIndex + 1 + Math.floor(Math.random() * (TEST_SAMPLES.length - 1))) % TEST_SAMPLES.length;
  const sample = TEST_SAMPLES[currentIndex];
  const pixels = testPixels.subarray(currentIndex * IMAGE_SIZE, (currentIndex + 1) * IMAGE_SIZE);
  const image = context.createImageData(28, 28);
  for (let i = 0; i < pixels.length; i++) {
    image.data[i * 4] = pixels[i];
    image.data[i * 4 + 1] = pixels[i];
    image.data[i * 4 + 2] = pixels[i];
    image.data[i * 4 + 3] = 255;
  }
  context.putImageData(image, 0, 0);
  canvas.setAttribute("aria-label", `Fashion-MNIST test image ${sample.id}: ${LABELS[sample.label]}`);
  document.getElementById("sample-id").textContent = `Test sample #${sample.id} · 28 × 28 grayscale`;
  document.getElementById("actual-label").textContent = LABELS[sample.label];
  clearResults();
}

function createRequestBody(pixels) {
  // Match the notebook's float32, [0, 1] input, with no extra normalization.
  const values = Array.from(pixels, pixel => Math.fround(pixel / 255).toPrecision(9));
  return `${pixels.length} ${values.join(" ")}`;
}

function parseLogits(text) {
  const fields = text.trim().split(/\s+/);
  if (fields.length !== LABELS.length + 1 || fields[0] !== String(LABELS.length)) {
    throw new Error("Invalid ESP32 response: expected a count of 10 followed by 10 logits.");
  }
  const logits = fields.slice(1).map(Number);
  if (!logits.every(Number.isFinite)) {
    throw new Error("Invalid ESP32 response: every logit must be a finite number.");
  }
  return { logits, raw: fields.slice(1) };
}

function showLogits({ logits, raw }, duration) {
  let winner = 0;
  for (let i = 1; i < logits.length; i++) {
    if (logits[i] > logits[winner]) winner = i;
  }
  for (let i = 0; i < rows.length; i++) {
    rows[i].value.textContent = raw[i];
    rows[i].row.classList.toggle("winner", i === winner);
    rows[i].tag.hidden = i !== winner;
  }
  const matches = winner === TEST_SAMPLES[currentIndex].label;
  prediction.textContent = LABELS[winner];
  predictionCard.className = `prediction ${matches ? "match" : "mismatch"}`;
  comparison.textContent = matches ? "Matches the actual label." : "Different from the actual label.";
  elapsed.textContent = `${Math.round(duration)} ms round trip`;
}

async function runInference(selectNew) {
  if (busy || !form.reportValidity()) return;
  let url;
  try {
    url = new URL(endpoint.value.trim());
    if (!["http:", "https:"].includes(url.protocol) || url.username || url.password) {
      throw new Error("Enter an HTTP or HTTPS inference URL without credentials.");
    }
  } catch (error) {
    setStatus(error instanceof TypeError ? "Enter a valid URL, for example http://192.168.0.100/." : error.message, true);
    return;
  }

  if (selectNew) selectRandomImage();
  else clearResults();
  endpoint.value = url.href;
  try { localStorage.setItem(STORAGE_KEY, url.href); } catch { /* Storage is optional. */ }

  const pixels = testPixels.subarray(currentIndex * IMAGE_SIZE, (currentIndex + 1) * IMAGE_SIZE);
  const body = createRequestBody(pixels);
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
  const started = performance.now();
  setBusy(true);
  setStatus("Waiting for inference results from ESP32…");

  try {
    const response = await fetch(url.href, {
      method: "POST",
      headers: { "Content-Type": "text/plain;charset=UTF-8" },
      body,
      mode: "cors",
      credentials: "omit",
      signal: controller.signal,
    });
    // The browser supplies Content-Length. Do not set this forbidden header.
    const text = await response.text();
    if (!response.ok) {
      const detail = text.trim().slice(0, 180);
      throw new Error(`ESP32 returned HTTP ${response.status}${detail ? `: ${detail}` : "."}`);
    }
    showLogits(parseLogits(text), performance.now() - started);
    setStatus("Inference complete. The highlighted row is the predicted label.");
  } catch (error) {
    prediction.textContent = "No prediction";
    comparison.textContent = "The request did not return valid logits. You can retry this image.";
    if (error.name === "AbortError") {
      setStatus("Request timed out after 15 seconds. Check the ESP32 address and connection.", true);
    } else if (error instanceof TypeError) {
      setStatus("Cannot read the ESP32 response. Check the URL, Wi-Fi, browser local-network permission, and firmware CORS support.", true);
    } else {
      setStatus(error.message, true);
    }
  } finally {
    clearTimeout(timeout);
    setBusy(false);
  }
}

function initialize() {
  if (!context) throw new Error("This browser cannot display the test images.");
  const decoded = atob(TEST_PIXELS_BASE64);
  testPixels = Uint8Array.from(decoded, character => character.charCodeAt(0));
  if (testPixels.length !== TEST_SAMPLES.length * IMAGE_SIZE) {
    throw new Error("The embedded test dataset is incomplete.");
  }

  const table = document.getElementById("logits");
  for (let i = 0; i < LABELS.length; i++) {
    const row = document.createElement("tr");
    const id = document.createElement("td");
    const label = document.createElement("td");
    const value = document.createElement("td");
    const tag = document.createElement("span");
    id.textContent = String(i);
    label.append(document.createTextNode(LABELS[i]));
    tag.className = "winner-tag";
    tag.textContent = "Predicted";
    tag.hidden = true;
    label.append(tag);
    row.append(id, label, value);
    table.append(row);
    rows.push({ row, value, tag });
  }

  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) endpoint.value = saved;
  } catch { /* The UI also works when browser storage is unavailable. */ }

  document.getElementById("dataset-info").textContent = `${TEST_SAMPLES.length} embedded test images · 10 per class. `;
  selectRandomImage();
  setStatus("Ready. Enter your ESP32 URL, then choose an inference action.");
  form.addEventListener("submit", event => {
    event.preventDefault();
    void runInference(true);
  });
  retryButton.addEventListener("click", () => void runInference(false));
}

try {
  initialize();
} catch (error) {
  randomButton.disabled = true;
  retryButton.disabled = true;
  setStatus(error.message, true);
}
